const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define region along Lower Mississippi River
  const arkansasCity = ee.Geometry.Point([-91.2068, 33.6076]);
  const vicksburg = ee.Geometry.Point([-90.8779, 32.3526]);
  const natchez = ee.Geometry.Point([-91.4032, 31.5604]);

  // Create buffer around these points to cover river corridor
  const roi = ee.FeatureCollection([
    ee.Feature(arkansasCity.buffer(15000)),
    ee.Feature(vicksburg.buffer(15000)),
    ee.Feature(natchez.buffer(15000))
  ]).geometry().dissolve();

  // 2. Get Sentinel-1 SAR data for both dates (±5 days window)
  const date2017Start = '2017-03-14';
  const date2017End = '2017-03-24';
  const date2019Start = '2019-03-14';
  const date2019End = '2019-03-24';

  let col2017 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(roi)
    .filterDate(date2017Start, date2017End)
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'));

  let col2019 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(roi)
    .filterDate(date2019Start, date2019End)
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'));

  const size2017 = col2017.size().getInfo();
  const size2019 = col2019.size().getInfo();

  console.log(`2017 Images: ${size2017}`);
  console.log(`2019 Images: ${size2019}`);

  if (size2017 === 0 || size2019 === 0) {
    console.log("Missing data for one or both periods");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Process water detection (VV < -15 dB typically indicates water)
  const img2017 = col2017.select('VV').median();
  const img2019 = col2019.select('VV').median();

  const waterThreshold = -15;
  const water2017 = img2017.lt(waterThreshold);
  const water2019 = img2019.lt(waterThreshold);

  // 4. Calculate water extent (pixel count and area)
  const pixelArea = ee.Image.pixelArea();

  const stats2017 = water2017.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2019 = water2019.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const count2017 = water2017.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const count2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const area2017 = stats2017.get('VV').getInfo();
  const area2019 = stats2019.get('VV').getInfo();
  const pixels2017 = count2017.get('VV').getInfo();
  const pixels2019 = count2019.get('VV').getInfo();

  console.log(`2017 Water Pixels: ${pixels2017}, Area: ${(area2017/1e6).toFixed(2)} km2`);
  console.log(`2019 Water Pixels: ${pixels2019}, Area: ${(area2019/1e6).toFixed(2)} km2`);

  // 5. Validation and answer
  if (area2017 === null || area2019 === null || pixels2017 === null || pixels2019 === null) {
    console.log("Calculation failed");
    console.log("<answer>C3</answer>");
    return;
  }

  if (pixels2017 === 0 || pixels2019 === 0) {
    console.log("No valid water pixels detected");
    console.log("<answer>C2</answer>");
    return;
  }

  if (area2019 > area2017) {
    console.log(`Water extent increased by ${((area2019-area2017)/1e6).toFixed(2)} km2`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Water extent decreased or unchanged by ${((area2017-area2019)/1e6).toFixed(2)} km2`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
